function validate(input) {
  const [{ Activity = [] }] = input;
  const keys = new Set();
  for (const [player, device, date, games] of Activity) {
    if (player === null || date === null) return 'player_id and event_date are required.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `event_date ${date} is not YYYY-MM-DD.`;
    const key = `${player}|${date}`;
    if (keys.has(key)) return `Player ${player} has two rows on ${date}.`;
    keys.add(key);
    if (games !== null && games < 0) return 'games_played cannot be negative.';
  }
  return null;
}

