function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // Start dates sit next to month, leap-day and year boundaries so "the next day" crosses them.
  const starts = [[2016, 1, 30], [2016, 2, 27], [2016, 12, 30], [2017, 2, 26], [2018, 6, 14]];
  const day = (base, offset) => new Date(Date.UTC(base[0], base[1] - 1, base[2] + offset)).toISOString().slice(0, 10);
  // The player count is never a multiple of 8, so the fraction never ends in an exact half at the third decimal.
  const players = size === 'small' ? 1 + pick(4) : 399;
  const rows = size === 'small' ? pick(9) : 2000;
  const spread = size === 'small' ? 4 : 12;
  const base = [], Activity = [], seen = new Set();
  for (let p = 1; p <= players; p++) base[p] = [...starts[pick(starts.length)]];
  if (size === 'large') for (let p = 1; p <= players; p++) base[p][2] += pick(20);
  const add = player => {
    const date = day(base[player], pick(spread));
    if (seen.has(`${player}|${date}`)) return;
    seen.add(`${player}|${date}`);
    Activity.push([player, 1 + pick(5), date, pick(8)]);
  };
  if (size === 'large') for (let p = 1; p <= players; p++) add(p);
  for (let tries = 0; Activity.length < rows && tries < rows * 20; tries++) add(1 + pick(players));
  return [{ Activity }];
}
